+        "mode={} encode_mib_s={:.2} decode_mib_s={:.2} encoded_hash={:016x} decoded_hash={:016x}",
+        if hd != 0 { "hd" } else { "std" },
+        (enc_bytes as f64 / (1024.0 * 1024.0)) / enc_elapsed.as_secs_f64(),
+        (dec_bytes as f64 / (1024.0 * 1024.0)) / dec_elapsed.as_secs_f64(),
+        fnv1a64(&encoded[..encoded_len]),
+        fnv1a64(&decoded[..decoded_len]),
+    );
+}
+
+fn main() {
+    unsafe {
+        bench_mode(0, 120);
+        bench_mode(1, 120);
+    }
+}
